//! Long-running task identity, progress reports and cooperative cancellation.

use std::fmt;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};

use serde::{Deserialize, Serialize};

use crate::error::{PortError, PortResult};

/// Identifier of a background task (package install, first-run setup…). Opaque string,
/// generated by the application layer.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct TaskId(String);

impl TaskId {
    pub fn new(id: impl Into<String>) -> Self {
        Self(id.into())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for TaskId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ProgressStage {
    /// Reading catalogs, resolving what to install.
    Resolving,
    Downloading,
    Verifying,
    Extracting,
    /// Post-install hooks, config generation.
    Configuring,
    /// First start of a service (e.g. `mysqld --initialize-insecure`).
    Initializing,
    /// An external program is running (`git clone`, Composer); `message` carries its output lines.
    Running,
}

/// One progress report. `done`/`total` are in bytes while downloading/extracting, otherwise
/// in abstract steps; `total` is `None` when unknown (indeterminate bar).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Progress {
    pub stage: ProgressStage,
    pub done: u64,
    pub total: Option<u64>,
    /// What is being worked on, developer-facing (`php-8.3.14`).
    pub subject: Option<String>,
    /// One line of human-readable output (a program's output while `Running`), shown in a log.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
}

impl Progress {
    pub fn new(stage: ProgressStage, done: u64, total: Option<u64>) -> Self {
        Self { stage, done, total, subject: None, message: None }
    }

    pub fn with_subject(mut self, subject: impl Into<String>) -> Self {
        self.subject = Some(subject.into());
        self
    }

    pub fn with_message(mut self, message: impl Into<String>) -> Self {
        self.message = Some(message.into());
        self
    }

    /// 0.0–1.0 when the total is known.
    pub fn fraction(&self) -> Option<f64> {
        self.total.filter(|t| *t > 0).map(|t| (self.done as f64 / t as f64).clamp(0.0, 1.0))
    }
}

/// Cooperative cancellation flag shared between the caller and a long operation.
/// Adapters call [`CancelFlag::check`] between chunks and return [`PortError::Cancelled`].
#[derive(Debug, Clone, Default)]
pub struct CancelFlag(Arc<AtomicBool>);

impl CancelFlag {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn cancel(&self) {
        self.0.store(true, Ordering::SeqCst);
    }

    pub fn is_cancelled(&self) -> bool {
        self.0.load(Ordering::SeqCst)
    }

    pub fn check(&self) -> PortResult<()> {
        if self.is_cancelled() { Err(PortError::Cancelled) } else { Ok(()) }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fraction_is_clamped_and_optional() {
        assert_eq!(Progress::new(ProgressStage::Downloading, 50, Some(200)).fraction(), Some(0.25));
        assert_eq!(Progress::new(ProgressStage::Downloading, 500, Some(200)).fraction(), Some(1.0));
        assert_eq!(Progress::new(ProgressStage::Downloading, 5, None).fraction(), None);
        assert_eq!(Progress::new(ProgressStage::Downloading, 5, Some(0)).fraction(), None);
    }

    #[test]
    fn cancel_flag_is_shared_between_clones() {
        let a = CancelFlag::new();
        let b = a.clone();
        assert!(b.check().is_ok());
        a.cancel();
        assert_eq!(b.check(), Err(PortError::Cancelled));
    }
}
